async () => {
  const out = [];
  let doc = document;
  for (let p = 1; p <= 17; p++) {
    let d = doc;
    if (p > 1) {
      const f = document.forms[0];
      const fd = new FormData(f);
      const base = await fetch('/Devices.aspx').then(r=>r.text());
      const bd = new DOMParser().parseFromString(base,'text/html');
      const fd2 = new FormData(bd.forms[0]);
      fd2.set('__EVENTTARGET','gv'); fd2.set('__EVENTARGUMENT','Page$'+p);
      const t = await fetch('/Devices.aspx',{method:'POST',body:new URLSearchParams(fd2)}).then(r=>r.text());
      d = new DOMParser().parseFromString(t,'text/html');
    }
    for (const r of d.querySelectorAll('tr')) {
      const c=[...r.children].map(x=>x.innerText??x.textContent);
      if (/^D\d+/.test((c[1]||'').trim())) out.push(c.slice(1,4).map(s=>s.trim()).join(' '));
    }
  }
  return out.filter(s=>/ (1004|1011|1026) /.test(s+' '));
}

