async () => {
  const res = {};
  for (const [url, key] of [['/Residents.aspx','res'],['/Devices.aspx','dev']]) {
    const base = await fetch(url).then(r=>r.text());
    const bd = new DOMParser().parseFromString(base,'text/html');
    const rows = [];
    let p = 1, d = bd;
    while (true) {
      const trs=[...d.querySelectorAll('tr')].map(r=>[...r.children].map(c=>c.textContent.trim()));
      const data = trs.filter(c=>c.length===5 && /^\d+$/.test(c[0]));
      rows.push(...data.map(c=>c.slice(1,4).join(' ')));
      const links=[...d.querySelectorAll('a')].map(a=>a.getAttribute('href')).filter(h=>h&&h.includes('Page$'));
      p++;
      if (!links.some(h=>h.includes("Page$"+p+"'"))) { if (p>40) break; if (p>25) break; }
      const fd2 = new FormData(bd.forms[0]);
      fd2.set('__EVENTTARGET','gv'); fd2.set('__EVENTARGUMENT','Page$'+p);
      const t = await fetch(url,{method:'POST',body:new URLSearchParams(fd2)}).then(r=>r.text());
      d = new DOMParser().parseFromString(t,'text/html');
      if (p>25) break;
    }
    res[key]=[...new Set(rows)];
  }
  return {resFilter: res.res.filter(s=>/ (1004|1011|1026) /.test(s+' ')||/Dev Alder|Kai/.test(s)), resCount: res.res.length, devFilter: res.dev.filter(s=>/ (1004|1011|1026) /.test(s+' ')), devCount: res.dev.length};
}

